<script setup lang="ts">
import { nextTick, onBeforeUnmount, onMounted, ref, toRef, watch } from 'vue'
import { X } from '@lucide/vue'
import { useOverlayBackClose } from '@/ui/overlay-back-stack'

const props = withDefaults(defineProps<{ open: boolean; title?: string; closeLabel?: string; position?: 'bottom' | 'center'; closable?: boolean }>(), { title: '', closeLabel: '关闭', position: 'bottom', closable: true })
const emit = defineEmits<{ close: [] }>()
const dialog = ref<HTMLDialogElement>()
// 安卓返回手势优先关闭弹窗（而不是后退页面）
useOverlayBackClose(toRef(props, 'open'), () => emit('close'))

function sync(): void {
  if (!dialog.value) return
  if (props.open && !dialog.value.open) {
    if (typeof dialog.value.showModal === 'function') dialog.value.showModal()
    else dialog.value.setAttribute('open', '')
    // 将焦点留在弹窗容器而非第一个可聚焦元素（如搜索框），避免唤起输入键盘
    dialog.value.focus({ preventScroll: true })
  }
  if (!props.open && dialog.value.open) {
    if (typeof dialog.value.close === 'function') dialog.value.close()
    else dialog.value.removeAttribute('open')
  }
}

/**
 * Escape/Android 返回触发原生 cancel 时，先阻止浏览器自动关闭，交给业务层决定是否关闭。
 * 这样业务可以区分用户主动取消和原生 WebView 的意外 close。
 */
function onCancel(event: Event): void {
  if (!props.open) return
  event.preventDefault()
  emit('close')
}

/** 原生 dialog 被外部关闭时只恢复显示，不把系统行为误判成业务取消。 */
function onNativeClose(): void {
  if (!props.open) return
  nextTick(sync)
}

function onKeydown(event: KeyboardEvent): void {
  if (event.key === 'Escape' && props.open) {
    event.preventDefault()
    emit('close')
  }
}

onMounted(() => { sync(); document.addEventListener('keydown', onKeydown) })
onBeforeUnmount(() => document.removeEventListener('keydown', onKeydown))
watch(() => props.open, () => nextTick(sync))
</script>

<template>
  <dialog ref="dialog" tabindex="-1" :class="['app-dialog', `is-${props.position}`]" @cancel="onCancel" @close="onNativeClose" @click.self="emit('close')">
    <section class="dialog-panel" role="document">
      <header>
        <div class="dialog-header-content"><slot name="header"><h2>{{ title }}</h2></slot></div>
        <button v-if="closable" class="icon-button" type="button" :aria-label="closeLabel" @click="emit('close')"><X :size="22" /></button>
      </header>
      <div class="dialog-body"><slot /></div>
      <footer v-if="$slots.actions"><slot name="actions" /></footer>
    </section>
  </dialog>
</template>

