header { position: sticky; z-index: 1; top: 0; display: flex; min-height: 60px; align-items: center; gap: 8px; justify-content: space-between; padding: 0 var(--space-4); border-bottom: 1px solid var(--color-border); background: var(--color-surface); }
.dialog-header-content { min-width: 0; flex: 1; }
h2 { margin: 0; font-size: 18px; }
.icon-button { display: grid; width: 48px; height: 48px; place-items: center; border: 0; border-radius: 50%; background: transparent; color: var(--color-text-secondary); }
.icon-button:focus-visible { outline: 3px solid rgb(22 119 255 / 35%); }
.dialog-body { padding: var(--space-4); }
footer { display: flex; gap: var(--space-3); justify-content: flex-end; padding: var(--space-4); }
