.app-dialog.is-center { display: flex; align-items: center; justify-content: center; padding: 16px; height: auto; max-height: none; }
.app-dialog.is-center .dialog-panel { position: static; width: 100%; max-width: 280px; border-radius: var(--radius-lg); }
</style>
